import heapq

class RunningMedian:
    def __init__(self):
        self.lower = []  # max heap (stored as min heap with negation)
        self.upper = []  # min heap

    def add(self, x: float) -> None:
        # Add to lower heap (max heap simulated as min heap with negation)
        if not self.lower or x <= -self.lower[0]:
            heapq.heappush(self.lower, -x)
        else:
            heapq.heappush(self.upper, x)

        # Balance the heaps
        if len(self.lower) > len(self.upper) + 1:
            val = -heapq.heappop(self.lower)
            heapq.heappush(self.upper, val)
        elif len(self.upper) > len(self.lower):
            val = heapq.heappop(self.upper)
            heapq.heappush(self.lower, -val)

    def median(self) -> float:
        if len(self.lower) > len(self.upper):
            return -self.lower[0]
        else:
            return ( -self.lower[0] + self.upper[0] ) / 2
